#include <map>
#include <memory>
#include <vector>

struct Widget {
    /// A widget of the given size, in pixels.
    Widget(int width, int height);
    Widget(const char* name, double scale);
};

struct Arena {};

struct Point {
    int x;
    int y;
};

void build() {
    auto widget = std::make_unique<Widget>(800, 600);
    auto shared = std::make_shared<Widget>(800, 600);
    auto named = std::make_shared<Widget>("main", 2.0);
    auto pooled = std::allocate_shared<Widget>(Arena{}, 800, 600);
    std::vector<Widget> widgets;
    widgets.emplace_back(800, 600);
    std::vector<Point> points;
    points.emplace_back(1, 2);
    std::map<int, Widget> by_id;
    by_id.try_emplace(1, "main", 1.0);
}

